public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
  // create a new graph with the same structure as the input graph
  Graph<V,E> newGraph = graph.clone();

  // create a mapping from the input graph to the new graph
  Map<V, V> mapping = new HashMap<>();
  for (V vertex : graph.vertices()) {
    mapping.put(vertex, newGraph.getVertex(vertex.getId()));
  }

  // create an IsomorphicGraphMapping object with the mapping and the new graph
  return new IsomorphicGraphMapping<V,E>(mapping, newGraph);
}

public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    Graph<V, E> clonedGraph = new Graph<>();
    for (V vertex : graph.getVertices()) {
        clonedGraph.addVertex(vertex);
        for (E edge : graph.getEdges(vertex)) {
            clonedGraph.addEdge(edge);
        }
    }
    return new IsomorphicGraphMapping<>(clonedGraph, graph);
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    IsomorphicGraphMapping<V,E> result = new IsomorphicGraphMapping<V,E>();
    for (V vertex : graph.getVertices()) {
        result.addVertexMap(vertex, vertex);
    }
    for (E edge : graph.getEdges()) {
        result.addEdgeMap(edge, edge);
    }
    return result;
}

