public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
	// Create a set of vertices in the input graph
	Set<V> vertices = new HashSet<>();

	// Add vertices to the set
	for (int i = 0; i < target.getVertexCount(); i++) {
		V vertex = target.getVertexAt(i);
		if (!vertices.contains(vertex)) {
			vertices.add(vertex);
		}
	}

	// Create a set of edges in the input graph
	Set<E> edges = new HashSet<>();

	// Add edges to the set
	for (int i = 0; i < target.getEdgeCount(); i++) {
		E edge = target.getEdgeAt(i);
		if (!edges.contains(edge)) {
			edges.add(edge);
		}
	}

	// Create a bipartite graph with the same vertices and edges as the input graph
	Graph<V,E> bipartiteGraph = new Graph<>();

	// Add vertices to the bipartite graph
	for (int i = 0; i < vertices.size(); i++) {
		V vertex = vertices.get(i);
		bipartiteGraph.addVertex(vertex);
	}

	// Add edges to the bipartite graph
	for (int i = 0; i < edges.size(); i++) {
		E edge = edges.get(i);
		V source = edge.getSource();
		V target = edge.getTarget();
		bipartiteGraph.addEdge(source, target);
	}

	// Return the bipartite graph
	resultMap.put(target.getId(), bipartiteGraph);
}

