  * Tries to resolve the class names of the type parameters of a parameterized type using reflection.
  * [/ resolvedArgs] is an array of the resolved argument types. If [/ resolvedArgs] is null,
  * there was an issue resolving the arguments.
  */public static Opening resolveArguments(ParameterizedType genericType, Class<?> targetType) {
      if (genericType != null && targetType != null) {
          return ResolvedType.createParameterizedType(genericType, targetType, Collections.emptyMap(), Collections.emptyMap());
      }
      return null;
