public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            if (typeArgument instanceof Class) {
                resolvedArguments[i] = (Class<?>) typeArgument;
            } else if (typeArgument instanceof TypeVariable) {
                TypeVariable typeVariable = (TypeVariable) typeArgument;
                resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
            } else {
                resolvedArguments[i] = null;
            }
        }
        return resolvedArguments;
    }
    return null;
}

private static Class<?> resolveTypeVariable(TypeVariable typeVariable, Class<?> targetType) {
    String typeVariableName = typeVariable.getName();
    for (int i = 0; i < targetType.getTypeParameters().length; i++) {
        TypeVariable targetTypeVariable = targetType.getTypeParameters()[i];
        if (targetTypeVariable.getName().equals(typeVariableName)) {
            return targetTypeVariable.getBounds()[0];
        }
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType paramType = (ParameterizedType) genericType;
        Type[] typeArgs = paramType.getActualTypeArguments();
        Class<?>[] typeParams = targetType.getTypeParameters();
        Class<?>[] resolvedArgs = new Class<?>[typeArgs.length];
        for (int i = 0; i < typeArgs.length; i++) {
            if (typeArgs[i] instanceof Class) {
                resolvedArgs[i] = (Class<?>) typeArgs[i];
            } else if (typeArgs[i] instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) typeArgs[i];
                Type resolvedType = resolveTypeVariable(typeVar, targetType, typeParams);
                if (resolvedType instanceof Class) {
                    resolvedArgs[i] = (Class<?>) resolvedType;
                }
            }
        }
        return resolvedArgs;
    } else {
        return null;
    }
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArgs = parameterizedType.getActualTypeArguments();
        Class<?>[] result = new Class<?>[typeArgs.length];
        for (int i = 0; i < typeArgs.length; i++) {
            Type typeArg = typeArgs[i];
            if (typeArg instanceof Class) {
                result[i] = (Class<?>) typeArg;
            } else if (typeArg instanceof TypeVariable) {
                TypeVariable typeVariable = (TypeVariable) typeArg;
                TypeVariable[] typeVariables = targetType.getTypeParameters();
                for (int j = 0; j < typeVariables.length; j++) {
                    if (typeVariables[j].getName().equals(typeVariable.getName())) {
                        result[i] = (Class<?>) typeVariables[j].getBounds()[0];
                        break;
                    }
                }
            }
        }
        return result;
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
	if (!(genericType instanceof ParameterizedType)) {
		return null;
	}

	ParameterizedType parameterizedType = (ParameterizedType) genericType;
	Type[] typeArguments = parameterizedType.getActualTypeArguments();

	if (typeArguments.length == 0) {
		return null;
	}

	Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
	for (int i = 0; i < typeArguments.length; i++) {
		Type typeArgument = typeArguments[i];
		if (typeArgument instanceof Class) {
			resolvedArguments[i] = (Class<?>) typeArgument;
		} else if (typeArgument instanceof TypeVariable) {
			resolvedArguments[i] = resolveTypeVariable(targetType, (TypeVariable<?>) typeArgument);
		} else if (typeArgument instanceof ParameterizedType) {
			resolvedArguments[i] = resolveParameterizedType(targetType, (ParameterizedType) typeArgument);
		} else if (typeArgument instanceof WildcardType) {
			resolvedArguments[i] = resolveWildcardType(targetType, (WildcardType) typeArgument);
		} else {
			return null;
		}
	}

	return resolvedArguments;
}

private static Class<?> resolveTypeVariable(Class<?> targetType, TypeVariable<?> typeVariable) {
	if (targetType.getTypeParameters().length != typeVariable.getGenericDeclaration().getTypeParameters().length) {
		return null;
	}

	for (int i = 0; i < targetType.getTypeParameters().length; i++) {
		if (typeVariable.equals(targetType.getTypeParameters()[i])) {
			return targetType.getActualTypeArguments()[i];
		}
	}

	return null;
}

