public List<TimeRange> buildTimeRanges(long start, long end) {
  List<TimeRange> timeRanges = new ArrayList<>();

  while (start < end) {
    long nextStart = start + FETCH_DATA_DURATION;
    if (nextStart > end) {
      nextStart = end;
    }
    timeRanges.add(new TimeRange(start, nextStart));
    start = nextStart;
  }

  return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start,long end){
int fetchDataDuration = 120000;
List<TimeRange> timeRanges = new ArrayList<>();

if(end - start > fetchDataDuration){
timeRanges.add(new TimeRange(start, start + fetchDataDuration));
long remainingTime = end - (start + fetchDataDuration);
while(remainingTime > fetchDataDuration){
timeRanges.add(new TimeRange(timeRanges.get(timeRanges.size() - 1).getEnd(), timeRanges.get(timeRanges.size() - 1).getEnd() + fetchDataDuration));
remainingTime -= fetchDataDuration;
}

if(remainingTime > 0){
timeRanges.add(new TimeRange(timeRanges.get(timeRanges.size() - 1).getEnd(), end));
}
}

return timeRanges;
}

public class TimerangeUtils {
    private static final long FETCH_DATA_DURATION = 10000L; // 10 seconds

    public static List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        Instant startInstant = Instant.ofEpochMilli(start);
        Instant endInstant = Instant.ofEpochMilli(end);
        while (startInstant.isBefore(endInstant)) {
            long duration = ChronoUnit.MILLIS.between(startInstant, endInstant);
            if (duration > FETCH_DATA_DURATION) {
                endInstant = startInstant.plus(FETCH_DATA_DURATION, ChronoUnit.MILLIS);
            } else {
                timeRanges.add(new TimeRange(startInstant, endInstant));
                startInstant = endInstant;
            }
        }
        return timeRanges;
    }
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start + FETCH_DATA_DURATION <= end) {
        timeRanges.add(new TimeRange(start, start + FETCH_DATA_DURATION));
        start += FETCH_DATA_DURATION;
    }
    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;
    while (start < end) {
        long nextEnd = Math.min(start + duration, end);
        timeRanges.add(TimeRange.create(start, nextEnd));
        start = nextEnd;
    }
    return timeRanges;
}

