    // Step 1: Check if byteArrayValue is null
    if (byteArrayValue == null) {
        // If it is null, we need to add the specified number of null bytes to the byte vector
        for (int i = 0; i < byteLength; i++) {
            this.add((byte) 0);
        }
        return this;
    }

    // Step 2: Check if byteOffset is within bounds
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset is out of bounds: " + byteOffset);
    }

    // Step 3: Check if byteLength is valid
    if (byteLength < 0 || byteLength > (byteArrayValue.length - byteOffset)) {
        throw new IndexOutOfBoundsException("byteLength is out of bounds: " + byteLength);
    }

    // Step 4: Add the bytes to the byte vector
    for (int i = byteOffset; i < (byteOffset + byteLength); i++) {
        this.add(byteArrayValue[i]);
    }

    return this;
}

