  if (decode) {
    path = URLDecoder.decode(path, "UTF-8");
  }
  String[] segments = path.split("/");
  for (String segment : segments) {
    if (segment.isEmpty()) {
      continue;
    }
    pathSegments.add(new PathSegmentImpl(segment, decode));
  }
  return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] segments = path.split("/");
    for (String segment : segments) {
        if (!segment.isEmpty()) {
            if (decode) {
                segment = URLDecoder.decode(segment, "UTF-8");
            }
            pathSegments.add(new PathSegmentImpl(segment, decode));
        }
    }
    return pathSegments;
}

public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
	List<PathSegmentImpl> segments = new ArrayList<PathSegmentImpl>();
	String path = u.getPath();
	if (path.isEmpty()) {
		return segments;
	}
	int start = path.charAt(0) == '/' ? 1 : 0;
	int end = path.length();
	int i;
	while ((i = path.indexOf('/', start)) != -1 && i < end) {
		String segment = path.substring(start, i);
		if (segment.isEmpty()) {
			if (decode) {
				segment = UriCodec.decode(segment, u.getCharset(), true);
			}
			segments.add(new PathSegmentImpl(segment, false));
		} else {
			segments.add(new PathSegmentImpl(segment, true));
		}
		start = i + 1;
	}
	if (start < end) {
		String segment = path.substring(start, end);
		if (segment.isEmpty()) {
			if (decode) {
				segment = UriCodec.decode(segment, u.getCharset(), true);
			}
			segments.add(new PathSegmentImpl(segment, false));
		} else {
			segments.add(new PathSegmentImpl(segment, true));
		}
	}
	return segments;
}

