private void pop(final String descriptor) {
    // Parse the type or method descriptor.
    String[] typeNames = descriptor.split(" ");

    // Pop the types from the output frame stack.
    for (String typeName : typeNames) {
        popType(typeName);
    }
}

public void pop(String descriptor) {
	// Pop types from the output frame stack based on the given descriptor
	// The types are popped from the stack in the reverse order of their appearance in the descriptor
	String[] types = descriptor.split("\\s*,\\s*");
	for (int i = types.length - 1; i >= 0; i--) {
		String type = types[i];
		if (type.equals("J") || type.equals("D")) {
			// Pop long or double value
			// Note: longs and doubles are represented as two stack values in the output frame stack
			popDouble();
		} else if (type.equals("L")) {
			// Pop reference value
			popReference();
		} else if (type.equals("I")) {
			// Pop integer value
			popInteger();
		} else if (type.equals("F")) {
			// Pop float value
			popFloat();
		} else if (type.equals("B")) {
			// Pop boolean value
			popBoolean();
		} else if (type.equals("S")) {
			// Pop short value
			popShort();
		} else if (type.equals("Z")) {
			// Pop byte value
			popByte();
		} else if (type.equals("C")) {
			// Pop char value
			popChar();
		}
	}
}

