public void addToIndex(V sourceVertex, V targetVertex, E e) {

    // Get the existing index entry for the source vertex, or create a new one if it doesn't exist
    Map<V, Set<E>> sourceVertexIndex = vertexIndex.get(sourceVertex);
    if (sourceVertexIndex == null) {
        sourceVertexIndex = new HashMap<>();
        vertexIndex.put(sourceVertex, sourceVertexIndex);
    }

    // Get the existing index entry for the target vertex, or create a new one if it doesn't exist
    Map<V, Set<E>> targetVertexIndex = vertexIndex.get(targetVertex);
    if (targetVertexIndex == null) {
        targetVertexIndex = new HashMap<>();
        vertexIndex.put(targetVertex, targetVertexIndex);
    }

    // Add the edge to the index
    sourceVertexIndex.put(targetVertex, e);
    targetVertexIndex.put(sourceVertex, e);
}

