public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double xCenter = box.getCenter().x;
    double yMin = box.getMin().y;
    double yMax = box.getMax().y;
    double xMin = box.getMin().x;
    double xMax = box.getMax().x;
    double width = xMax - xMin;
    double height = yMax - yMin;
    double midX = xCenter;
    double midY = yMin + height / 2;
    double splitX = midX - width / 2;
    double splitY = midY;
    Box2D box1 = new Box2D(xMin, yMin, splitX, yMax);
    Box2D box2 = new Box2D(splitX, yMin, xMax, yMax);
    return new Pair<>(box1, box2);
}

