public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 1000) {
        return desiredCapacity;
    }

    // Find the next prime number
    int prime = 1009;
    while (true) {
        if (isPrime(prime)) {
            break;
        }
        prime++;
    }

    // Find the closest prime number to the desired capacity
    int closestPrime = prime;
    for (int i = prime - 1; i >= 0; i--) {
        if (isPrime(i) && Math.abs(i - desiredCapacity) < Math.abs(closestPrime - desiredCapacity)) {
            closestPrime = i;
        }
    }

    return closestPrime;
}

