private Map<String, Object> buildContent(JsonObject jsonObject) {
   Map<String, Object> content = Maps.newHashMap();
   for (String field : jsonObject.keySet()) {
     if (jsonObject.has(field) && jsonObject.get(field).isJsonArray()) {
       JsonArray array = jsonObject.get(field).getAsJsonArray();
       List<Object> list = Lists.newArrayList();
       for (JsonElement element : array) {
         list.add(getElement(element));
         list.add(buildContent(element.getAsJsonObject()));
       }
       content.put(field, list);
     } else {
       content.put(field, getElement(jsonObject.get(field)));
     }
   }
   return content;
 }

private Object getElement(JsonElement element) {
   if (element.isJsonPrimitive()) {
     return element.getAsString();
   } else if (element.isJsonObject()) {
     return buildContent(element.getAsJsonObject());
   } else {
     return null;
   }
 }

