    }
    int length = str.length();
    StringBuilder buf = new StringBuilder(length);
    for (int i = 0; i < length; i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 < length) {
                char nextChar = str.charAt(i + 1);
                if (nextChar == 'n') {
                    buf.append('\n');
                    i++;
                } else if (nextChar == 'r') {
                    buf.append('\r');
                    i++;
                } else if (nextChar == 't') {
                    buf.append('\t');
                    i++;
                } else if (nextChar == 'b') {
                    buf.append('\b');
                    i++;
                } else if (nextChar == 'f') {
                    buf.append('\f');
                    i++;
                } else if (nextChar == '/') {
                    buf.append('/');
                    i++;
                } else if (nextChar == '\\') {
                    buf.append('\\');
                    i++;
                } else if (nextChar == 'u') {
                    if (i + 5 < length) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            buf.append((char) Integer.parseInt(hex, 16));
                            i += 5;
                        } catch (NumberFormatException e) {
                            throw new Exception("Illegal hex character in escape sequence: " + hex, e);
                        }
                    } else {
                        throw new Exception("Incomplete escape sequence at end of string");
                    }
                } else {
                    buf.append('\\');
                }
            } else {
                buf.append('\\');
            }
        } else {
            buf.append(ch);
        }
    }
    return buf.toString();
}

