public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    // Check if the character buffer is large enough
    if (charBuffer.length < getUtfSize(constantPoolEntryIndex)) {
        throw new ArrayIndexOutOfBoundsException("Character buffer is not large enough to hold the complete string");
    }

    // Read the length of the string
    int stringLength = readUnsignedShort(constantPoolEntryIndex + 2);

    // Read the string
    for (int i = 0; i < stringLength; i++) {
        charBuffer[i] = (char) readUnsignedByte(constantPoolEntryIndex + 4 + i);
    }

    // Return the string
    return new String(charBuffer, 0, stringLength);
}

