public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
	// Check if we need to increase the size of the byte vector
	if (byteLength > buffer.length - index) {
		int newLength = buffer.length;
		while (newLength < index + byteLength) {
			newLength *= 2;
		}
		byte[] newBuffer = new byte[newLength];
		System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
		buffer = newBuffer;
	}

	// Copy the bytes from the input array to the byte vector
	if (byteArrayValue != null) {
		System.arraycopy(byteArrayValue, byteOffset, buffer, index, byteLength);
		index += byteLength;
	} else {
		// If the input array is null, fill the byte vector with null bytes
		Arrays.fill(buffer, index, index + byteLength, (byte) 0);
		index += byteLength;
	}

	return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Calculate the number of bytes that need to be added to the current capacity
    int numBytesToAdd = byteLength - (byteArrayValue.length - byteOffset);

    // If the current capacity is not enough, reallocate the byte array
    if (numBytesToAdd > 0) {
        byte[] newByteArray = new byte[byteArrayValue.length + numBytesToAdd];
        System.arraycopy(byteArrayValue, 0, newByteArray, 0, byteArrayValue.length);
        byteArrayValue = newByteArray;
    }

