        if (constant instanceof ConstantNameAndTypeInfo &&
                ((ConstantNameAndTypeInfo) constant).getName().equals(name) &&
                ((ConstantNameAndTypeInfo) constant).getDescriptor().equals(descriptor)) {
            return constantPoolIndex;
