  public static Class findClass(String className) throws ClassNotFoundException {
    if (className == null) {
      throw new IllegalArgumentException("className cannot be null");
    }
    // Strip any surrounding whitespace from the class name
    className = className.trim();
    // Check if the class name contains any forbidden characters
    if (className.contains(" ") || className.contains("\n") || className.contains("\r")) {
      throw new IllegalArgumentException("className cannot contain whitespace or newlines");
    }
    // Search for the class in the classpath
    Class clazz = Class.forName(className);
    if (clazz == null) {
      throw new ClassNotFoundException("Class " + className + " not found");
    }
    return clazz;
  }
}

