public static final <V> void reverse(V[] arr, int from, int to) {
	int length = to - from + 1;
	for (int i = 0; i < length / 2; i++) {
		int index1 = from + i;
		int index2 = to - i;
		// swap the elements
		V temp = arr[index1];
		arr[index1] = arr[index2];
		arr[index2] = temp;
	}
}

public static final <V> void reverse(V[] arr, int from, int to) {
  int left = from;
  int right = to;
  while (left < right) {
    V temp = arr[left];
    arr[left] = arr[right];
    arr[right] = temp;
    left++;
    right--;
  }
}

