private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> result = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<Pair<Pair<Integer,Integer>,E>> separators = new ArrayList<>();
        for (E neighbor : graph.getNeighbors(edge)) {
            separators.add(Pair.of(neighbor.getEndpoints(), edge));
        }
        result.add(Pair.of(separators, edge));
    }
    return result;
