private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    // Iterate over all edges in the graph
    for (E edge : graph.edgeSet()) {
        Pair<List<Pair<Integer, Integer>>, E> separatorPair = new Pair<>();

        // Compute the minimal separator of the edge
        Pair<Integer, Integer> startVertex = graph.getEdgeSource(edge);
        Pair<Integer, Integer> endVertex = graph.getEdgeTarget(edge);
        List<Pair<Integer, Integer>> minimalSeparator = computeMinimalSeparator(graph, startVertex, endVertex);

        // Add the minimal separator to the list
        separatorPair.setFirst(minimalSeparator);
        separatorPair.setSecond(edge);
        globalSeparatorList.add(separatorPair);
    }

    return globalSeparatorList;
}

