public ByteVector putInt(int intValue) {
	// automatically enlarge the byte vector if necessary
	int newLength = this.index + 4;
	if (newLength > this.data.length) {
		byte[] newData = new byte[Math.max(this.data.length << 1, newLength)];
		System.arraycopy(this.data, 0, newData, 0, this.data.length);
		this.data = newData;
	}

	// put the int value into the byte vector
	this.data[this.index++] = (byte) (intValue >>> 24);
	this.data[this.index++] = (byte) (intValue >>> 16);
	this.data[this.index++] = (byte) (intValue >>> 8);
	this.data[this.index++] = (byte) intValue;

	return this;
}

