private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    Graph<V,E> clique = new Graph<>();
    for (V vertex : vertices) {
        if (!clique.containsVertex(vertex)) {
            clique.addVertex(vertex);
            for (V neighbor : graph.getNeighbors(vertex)) {
                if (!clique.containsVertex(neighbor)) {
                    clique.addVertex(neighbor);
                    clique.addEdge(vertex, neighbor);
                }
            }
        }
    }
    return clique.getNumEdges() == clique.getNumVertices() * (clique.getNumVertices() - 1) / 2;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // check if the subgraph induced by the given vertices is complete, i.e. a clique
    if (vertices.size() <= 1) {
        return true;
    }
    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (vertex != otherVertex && !graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }
    return true;
}

