private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    // First, check if the number of vertices is equal to the number of edges.
    // If it's not, then the graph is not complete and we can return false.
    int numVertices = vertices.size();
    int numEdges = graph.getEdges(vertices).size();
    if (numVertices != numEdges) {
        return false;
    }

    // Second, check if every vertex is connected to every other vertex.
    // We can do this by iterating over the vertices and checking if each vertex is connected to every other vertex.
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.hasEdge(v1, v2)) {
                return false;
            }
        }
    }

    // If we make it past both checks, then the subgraph is a clique.
    return true;
}

