private void pop(String descriptor) {
    if (descriptor.charAt(0) == '(') {
        // If the descriptor is a method descriptor, pop its argument types
        for (int i = 1; i < descriptor.length(); i++) {
            if (descriptor.charAt(i) == 'L') {
                pop(descriptor.substring(i + 1, descriptor.indexOf(';', i)));
            } else {
                pop(descriptor.substring(i, i + 1));
            }
        }
    } else {
        // If the descriptor is not a method descriptor, pop the type
        pop(descriptor.substring(1));
    }
}

private void pop(final String descriptor) {
    int count = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        if (descriptor.charAt(i) == '(', descriptor.charAt(i) == '[') {
            count++;
        } else if (descriptor.charAt(i) == ')', descriptor.charAt(i) == ']') {
            count--;
        }
    }
    for (int i = 0; i < count; i++) {
        outputFrame.pop();
    }
}

