public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Check if the file is valid and can be parsed
    if (file == null || !file.exists() || file.length() == 0) {
        throw new IllegalArgumentException("Invalid file");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid time ranges");
    }

    // Parse the file and extract the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split(",");
            String threadName = tokens[0];
            long startTime = Long.parseLong(tokens[1]);
            long endTime = Long.parseLong(tokens[2]);
            long duration = endTime - startTime;
            threadSnapshots.add(new ThreadSnapshot(threadName, startTime, endTime, duration));
        }
    }

    // Filter the thread snapshots based on the time range provided
    List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
    for (ThreadSnapshot snapshot : threadSnapshots) {
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (snapshot.getStartTime() >= timeRange.getStartTime() && snapshot.getEndTime() <= timeRange.getEndTime()) {
                filteredSnapshots.add(snapshot);
                break;
            }
        }
    }

    return filteredSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split(",");
            if (tokens.length != 3) {
                continue;
            }
            long timestamp = Long.parseLong(tokens[0]);
            int threadId = Integer.parseInt(tokens[1]);
            String threadName = tokens[2];
            boolean include = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                    include = true;
                    break;
                }
            }
            if (include) {
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, threadName, timestamp);
                threadSnapshots.add(threadSnapshot);
            }
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    CpuProfileParser parser = new CpuProfileParser(file);
    parser.parse();
    List<ThreadData> threads = parser.getThreads();
    threadSnapshots = new ArrayList<>();
    for (ThreadData thread : threads) {
        boolean isInRange = false;
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (thread.getStartTime() >= range.getStartTime() && thread.getStartTime() <= range.getEndTime()) {
                isInRange = true;
                break;
            }
        }
        if (isInRange) {
            threadSnapshots.add(new ThreadSnapshot(thread));
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot snapshot = parseThreadSnapshot(line);
            if (snapshot != null && isInTimeRange(snapshot.getTimestamp(), timeRanges)) {
                threadSnapshots.add(snapshot);
            }
        }
    }
    return threadSnapshots;
}

private static boolean isInTimeRange(long timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timestamp >= timeRange.getStartTimestamp() && timestamp <= timeRange.getEndTimestamp()) {
            return true;
        }
    }
    return false;
}

